import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlTextComponent } from '@domg-wc/components/atom';
import {
    parseFormData,
    VlCheckboxComponent,
    VlDatepickerComponent,
    VlFieldsetComponent,
    VlFormLabelComponent,
    VlFormMessageComponent,
    VlInputFieldComponent,
    VlInputFieldMaskedComponent,
    VlRadioComponent,
    VlRadioGroupComponent,
    VlSelectComponent,
    VlSelectRichComponent,
    VlTextareaComponent,
    VlUploadComponent,
} from '@domg-wc/components/form';

registerWebComponents([
    VlFormLabelComponent,
    VlInputFieldComponent,
    VlInputFieldMaskedComponent,
    VlTextareaComponent,
    VlDatepickerComponent,
    VlSelectRichComponent,
    VlSelectComponent,
    VlRadioGroupComponent,
    VlRadioComponent,
    VlUploadComponent,
    VlCheckboxComponent,
    VlFormMessageComponent,
    VlFieldsetComponent,
    VlButtonComponent,
    VlTextComponent,
]);

// Opties met choices worden een groep in de select-rich.
document.querySelector('#geboorteplaats').options = [
    {
        label: 'België',
        value: '',
        choices: [
            { label: 'Hasselt', value: 'hasselt' },
            { label: 'Turnhout', value: 'turnhout' },
            { label: 'Knokke-Heist', value: 'knokke-heist' },
            { label: 'Waregem', value: 'waregem' },
            { label: 'Lier', value: 'lier' },
        ],
    },
    {
        label: 'Puerto Rico',
        value: '',
        choices: [{ label: 'Rio Piedras', value: 'rio piedras' }],
    },
];

document.querySelector('#hobbies').options = [
    { label: 'Padel', value: 'padel' },
    { label: 'Dans', value: 'dans' },
    { label: 'Drummen', value: 'drummen' },
    { label: 'Zwemmen', value: 'zwemmen' },
    { label: 'Boardgames', value: 'boardgames' },
    { label: 'Fietsen', value: 'fietsen' },
];

document.querySelector('#kinderen').options = [
    { label: '0', value: '0' },
    { label: '1', value: '1' },
    { label: '2', value: '2' },
    { label: '3', value: '3' },
    { label: '4', value: '4' },
    { label: '5 of meer', value: '5 of meer' },
];

// parseFormData geeft de waarden als object; een veld met multiple, zoals hobbies, geeft een array.
document.querySelector('#form').addEventListener('submit', (event) => {
    event.preventDefault();
    const data = parseFormData(event.target);
    console.log(data);
});
